{
  "decision": "PASS",
  "constraint_reviews": [
    {
      "constraint_id": "C1",
      "status": "SUPPORTED",
      "reason": "The quoted passage explicitly states each sister chromatid rests on one side of the plate, implying they are components of the duplicated chromosome at metaphase. The relation component_of is a reasonable abstraction for a grades 10-12 educational context.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C2",
      "status": "SUPPORTED",
      "reason": "The passage explicitly says sister chromatids are still tightly attached to each other by cohesin proteins at metaphase. The connected_by relation with cohesin as mediator is directly entailed.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C3",
      "status": "SUPPORTED",
      "reason": "The passage states that eventually all sister chromatids are attached via kinetochores to microtubules from opposing poles. This directly supports kinetochore_a attached_to spindle_pole_a as a simplified relation, appropriate for the audience.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C4",
      "status": "SUPPORTED",
      "reason": "Same passage supports attachment of the other sister chromatid's kinetochore to the opposite pole. The abstraction is consistent with the source.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C5",
      "status": "SUPPORTED",
      "reason": "The passage describes each chromatid being pulled rapidly toward the centrosome to which its microtubule is attached. The direction relation between sister chromatids and opposite poles is directly supported, though the fractional min/max bounds are a modeling choice.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C6",
      "status": "SUPPORTED",
      "reason": "The passage explicitly orders cohesin degradation before sister chromatid separation at anaphase onset. The event_order constraint is directly entailed.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C7",
      "status": "SUPPORTED",
      "reason": "The passage states chromosomes are aligned at the equatorial plate during metaphase. The state key aligned_at_metaphase_plate is a faithful abstraction.",
      "evidence_ids": ["E_70c610899421"]
    },
    {
      "constraint_id": "C8",
      "status": "SUPPORTED",
      "reason": "The passage states the chromosome will be oriented until kinetochores of sister chromatids face opposite poles. The face_opposite_poles relation is directly supported.",
      "evidence_ids": ["E_70c610899421"]
    }
  ],
  "goal_coverage": {
    "decision": "PASS",
    "missing_goals": []
  },
  "issues": [
    {
      "issue": "Cohesin degradation is a molecular event not directly visible at light microscopy; the video may need to use a simplified visual metaphor or label. This is a teaching simplification, not a misleading error, provided it is clarified.",
      "severity": "minor",
      "related_constraint_ids": ["C6"]
    },
    {
      "issue": "The metaphase plate is an imaginary plane, not a physical structure; if the animation depicts it as a solid barrier or membrane, that would be misleading. Human review should confirm correct representation.",
      "severity": "minor",
      "related_constraint_ids": ["C7"]
    },
    {
      "issue": "The contract does not explicitly forbid showing homolog pairing, but the user excluded it. The video must avoid depicting homolog pairing during metaphase/anaphase of mitosis. Human review should verify.",
      "severity": "major",
      "related_constraint_ids": ["C1", "C2", "C7"]
    }
  ],
  "reference_events": [
    {
      "event_role": "metaphase_alignment",
      "state": "chromosomes aligned at equatorial plate, sister chromatids attached to opposite poles, cohesin holding sisters together",
      "relations": ["component_of", "connected_by", "attached_to", "aligned_at_metaphase_plate", "face_opposite_poles"],
      "evidence_ids": ["E_70c610899421"],
      "quote": "Metaphase – The mitotic spindle is fully developed and centrosomes are at opposite poles. Chromosomes are aligned at the “equatorial plate”, and each sister chromatid rests on one side of the plate, with spindle fibers attached to them."
    },
    {
      "event_role": "anaphase_separation",
      "state": "cohesin degraded, sister chromatids separate and move toward opposite centrosomes",
      "relations": ["event_order(cohesin_degradation, sister_separation)", "direction(sister_chromatid_a toward spindle_pole_a)", "direction(sister_chromatid_b toward spindle_pole_b)"],
      "evidence_ids": ["E_70c610899421"],
      "quote": "Anaphase (“upward phase”): The cohesin proteins degrade, and the sister chromatids separate at the centromere. Each chromatid, now called a single chromosome, is pulled rapidly toward the centrosome to which its microtubule is attached."
    }
  ]
}
